const input = $input.first().json;
const body = input.body || input;
const demoMode = body.demo_mode === true || body.demo_mode === 'true';
const userId = body.user_id || 'demo-user';
const role = body.role || 'Senior ML Engineer';
const location = body.location || 'New York, United States';
const keywords = body.keywords || ['Python', 'LLM', 'AI'];
const remote = body.remote !== undefined ? body.remote : true;

const queries = [
  `${role} jobs ${location}`,
  `${role} ${keywords.slice(0,2).join(' ')} hiring 2025`,
  `${role} remote apply now`
];

return [{ json: {
  user_id: userId,
  role,
  location,
  keywords,
  remote,
  demo_mode: demoMode,
  queries,
  session_id: body.session_id || `jd_${Date.now()}`,
  triggered_at: new Date().toISOString()
} }];

const r = $input.first().json;
const criteria = $('\ud83d\udccb Load Search Criteria').first().json;

if (criteria.demo_mode) {
  return [{ json: { normalized: [
    { id: 'demo_001', title: 'Senior ML Engineer', company: 'OpenAI', location: 'New York, NY', url: 'https://openai.com/careers', salary: '$200k-$280k', remote: true, posted_at: new Date().toISOString(), source: 'demo' },
    { id: 'demo_002', title: 'Staff AI Engineer', company: 'Anthropic', location: 'Remote', url: 'https://anthropic.com/careers', salary: '$220k-$300k', remote: true, posted_at: new Date().toISOString(), source: 'demo' },
    { id: 'demo_003', title: 'Senior ML Engineer', company: 'Cohere', location: 'New York, NY', url: 'https://cohere.com/careers', salary: '$180k-$240k', remote: false, posted_at: new Date().toISOString(), source: 'demo' }
  ], source: 'serper', demo_mode: true } }];
}

const results = r.organic || r.jobs || [];
const normalized = results.slice(0, 10).map((j, i) => ({
  id: `serper_${Date.now()}_${i}`,
  title: j.title || 'Unknown',
  company: j.source || j.employer_name || 'Unknown',
  location: j.location || 'Unknown',
  url: j.link || j.job_apply_link || '',
  salary: j.salary || null,
  remote: (j.location || '').toLowerCase().includes('remote'),
  posted_at: j.date || new Date().toISOString(),
  source: 'serper'
}));
return [{ json: { normalized, source: 'serper', demo_mode: criteria.demo_mode } }];

const r = $input.first().json;
const criteria = $('\ud83d\udccb Load Search Criteria').first().json;

if (criteria.demo_mode) {
  return [{ json: { normalized: [
    { id: 'demo_004', title: 'ML Platform Engineer', company: 'Stripe', location: 'New York, NY', url: 'https://stripe.com/jobs', salary: '$190k-$260k', remote: false, posted_at: new Date().toISOString(), source: 'demo' },
    { id: 'demo_005', title: 'Senior AI Engineer', company: 'Notion', location: 'Remote', url: 'https://notion.so/jobs', salary: '$170k-$230k', remote: true, posted_at: new Date().toISOString(), source: 'demo' }
  ], source: 'youcom', demo_mode: true } }];
}

// You.com returns hits array with url, title, description, snippets
const hits = r.hits || r.web?.results || r.results || [];
const normalized = hits.slice(0, 10).map((j, i) => ({
  id: `youcom_${Date.now()}_${i}`,
  title: j.title || 'Unknown',
  company: j.description?.match(/at ([A-Z][a-zA-Z\s]+?)(?:\s*[-|]|$)/)?.[1]?.trim() || 'Unknown',
  location: 'Unknown',
  url: j.url || j.link || '',
  salary: null,
  remote: (j.description || j.title || '').toLowerCase().includes('remote'),
  posted_at: new Date().toISOString(),
  source: 'youcom',
  snippet: (j.snippets || [j.description]).join(' ').slice(0, 300)
})).filter(j => j.url && j.url.includes('http'));
return [{ json: { normalized, source: 'youcom', demo_mode: criteria.demo_mode } }];

const items = $input.all();
const allJobs = items.flatMap(item => item.json.normalized || []);
const seen = new Set();
const unique = allJobs.filter(job => {
  const key = `${job.title.toLowerCase()}_${job.company.toLowerCase()}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
}).filter(job => job.url && job.url.startsWith('http'));
const criteria = $('\ud83d\udccb Load Search Criteria').first().json;
return [{ json: {
  jobs: unique.slice(0, 15),
  total_found: unique.length,
  demo_mode: criteria.demo_mode,
  user_id: criteria.user_id,
  role: criteria.role,
  keywords: criteria.keywords,
  session_id: criteria.session_id
} }];

// Enrich top 5 job URLs with Firecrawl scraping for accurate Fit Scoring
// In demo mode, return jobs as-is with mock snippets
const d = $input.first().json;

if (d.demo_mode || d.jobs.length === 0) {
  const enriched = d.jobs.map(j => ({ ...j, jd_snippet: j.snippet || `${j.title} at ${j.company}. ${j.location}. Requires Python, ML, and LLM experience.` }));
  return [{ json: { ...d, jobs: enriched, enrichment_source: 'demo_passthrough' } }];
}

// Pass through for Firecrawl enrichment (Firecrawl node follows this)
// We tag top 5 for enrichment, rest pass through with snippet only
const top5 = d.jobs.slice(0, 5).map(j => ({ ...j, needs_enrichment: true }));
const rest = d.jobs.slice(5).map(j => ({ ...j, needs_enrichment: false, jd_snippet: j.snippet || '' }));
return [{ json: { ...d, jobs: [...top5, ...rest], enrichment_source: 'firecrawl' } }];

