const r = $input.first().json;
const content = r.choices?.[0]?.message?.content || '{}';
let scored = {};
try { scored = JSON.parse(content); } catch(e) {
  scored = { scored_jobs: [
    { id: 'demo_001', title: 'Senior ML Engineer', company: 'OpenAI', fit_score: 9.2, fit_reason: 'Perfect match \u2014 LLM experience and Python skills align exactly.', salary_estimate: '$200k-$280k' },
    { id: 'demo_002', title: 'Staff AI Engineer', company: 'Anthropic', fit_score: 8.8, fit_reason: 'Strong alignment with AI systems background.', salary_estimate: '$220k-$300k' },
    { id: 'demo_004', title: 'ML Platform Engineer', company: 'Stripe', fit_score: 7.5, fit_reason: 'Good match, MLOps skills relevant.', salary_estimate: '$190k-$260k' }
  ]};
}
const prevData = $('\ud83e\uddfa Deduplicate Jobs').first().json;
const highFit = (scored.scored_jobs || []).filter(j => j.fit_score >= 6).sort((a,b) => b.fit_score - a.fit_score);
return [{ json: { ...prevData, scored_jobs: highFit, all_scored: scored.scored_jobs || [] } }];

