const r = $input.first().json;
const content = r.choices?.[0]?.message?.content || '{}';
let intel = {};
try { intel = JSON.parse(content); } catch(e) {
  intel = { market_summary: 'Strong demand for ML Engineers in NYC. LLM and AI systems experience commands premium salaries.', avg_salary_range: '$180k-$280k', top_hiring_companies: ['OpenAI', 'Anthropic', 'Stripe', 'Cohere'], hot_skills: ['Python', 'LLM', 'RAG', 'MLOps', 'PyTorch'], remote_percentage: 60, competition_level: 'medium', recommendation: 'Apply to top 3 matches immediately \u2014 demand is high and these roles fill fast.' };
}
const prevData = $('\ud83d\udcca Parse Fit Scores').first().json;
return [{ json: { ...prevData, market_intel: intel } }];

const d = $input.first().json;
return [{ json: {
  status: 'success',
  branch: 'job_discovery',
  session_id: d.session_id,
  jobs_found: d.total_found || 0,
  high_fit_jobs: d.scored_jobs?.length || 0,
  top_jobs: d.scored_jobs?.slice(0, 5).map(j => ({
    title: j.title,
    company: j.company,
    fit_score: j.fit_score,
    fit_reason: j.fit_reason,
    salary: j.salary_estimate
  })),
  market_intel: d.market_intel,
  generated_at: new Date().toISOString()
}}];
